     1→import type { VercelRequest, VercelResponse } from '@vercel/node';
     2→import { getRedisClient } from '../lib/redis';
     3→
     4→interface LeaderboardEntry {
     5→  userId: string;
     6→  userName: string;
     7→  score: number;
     8→  rank: number;
     9→}
    10→
    11→export default async function handler(
    12→  req: VercelRequest,
    13→  res: VercelResponse
    14→) {
    15→  // CORS 설정
    16→  res.setHeader('Access-Control-Allow-Credentials', 'true');
    17→  res.setHeader('Access-Control-Allow-Origin', '*');
    18→  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS');
    19→  res.setHeader(
    20→    'Access-Control-Allow-Headers',
    21→    'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version'
    22→  );
    23→
    24→  if (req.method === 'OPTIONS') {
    25→    res.status(200).end();
    26→    return;
    27→  }
    28→
    29→  if (req.method !== 'GET') {
    30→    return res.status(405).json({ error: 'Method not allowed' });
    31→  }
    32→
    33→  try {
    34→    const { difficulty, limit = '100', userId } = req.query;
    35→
    36→    if (!difficulty || typeof difficulty !== 'string') {
    37→      return res.status(400).json({ error: 'Missing or invalid difficulty parameter' });
    38→    }
    39→
    40→    const topN = parseInt(limit as string, 10);
    41→    if (isNaN(topN) || topN < 1 || topN > 1000) {
    42→      return res.status(400).json({ error: 'Invalid limit parameter (must be 1-1000)' });
    43→    }
    44→
    45→    const redis = getRedisClient();
    46→    const leaderboardKey = `leaderboard:${difficulty}`;
    47→
    48→    // 상위 N명 조회 (점수 높은 순)
    49→    const topScores = await redis.zrange(leaderboardKey, 0, topN - 1, {
    50→      rev: true,
    51→      withScores: true,
    52→    });
    53→
    54→    // 사용자 이름 조회를 위한 userId 목록
    55→    const userIds: string[] = [];
    56→    const scores: number[] = [];
    57→
    58→    for (let i = 0; i < topScores.length; i += 2) {
    59→      userIds.push(topScores[i] as string);
    60→      scores.push(topScores[i + 1] as number);
    61→    }
    62→
    63→    // 사용자 정보 일괄 조회
    64→    const userDataPromises = userIds.map(async (id) => {
    65→      const userData = await redis.hgetall(`user:${id}`);
    66→      return userData?.name || `User ${id.slice(0, 8)}`;
    67→    });
    68→
    69→    const userNames = await Promise.all(userDataPromises);
    70→
    71→    // 리더보드 엔트리 생성
    72→    const leaderboard: LeaderboardEntry[] = userIds.map((id, index) => ({
    73→      userId: id,
