import { type Difficulty } from '../types/GameMode';
import { getCurrentUserId } from './auth';
import { supabase } from './supabase';

export interface LeaderboardEntry {
  userId: string;
  userName: string;
  score: number;
  rank: number;
}

export interface SubmitScoreResponse {
  success: boolean;
  isNewRecord: boolean;
  previousScore: number | null;
  newScore: number;
  rank: number | null;
  message?: string;
}

export interface LeaderboardResponse {
  success: boolean;
  difficulty: string;
  leaderboard: LeaderboardEntry[];
  currentUserRank: {
    rank: number;
    score: number;
  } | null;
  totalEntries: number;
}

/**
 * 사용자 ID 조회 (Supabase Auth 기반)
 */
export async function getUserId(): Promise<string> {
  return getCurrentUserId();
}

/**
 * 사용자 이니셜 조회
 */
export function getUserInitials(): string | null {
  return localStorage.getItem('userInitials');
}

/**
 * 사용자 이니셜 저장
 * @param initials 3자리 영어 대문자 (예: "ABC")
 */
export function setUserInitials(initials: string): boolean {
  // 검증: 정확히 3자리, 영어 대문자만
  const validation = /^[A-Z]{3}$/;
  if (!validation.test(initials)) {
    return false;
  }

  localStorage.setItem('userInitials', initials);
  return true;
}

/**
 * 이니셜이 설정되어 있는지 확인
 */
export function hasUserInitials(): boolean {
  const initials = getUserInitials();
  return initials !== null && /^[A-Z]{3}$/.test(initials);
}

/**
 * 점수 제출
 */
export async function submitScore(
  score: number,
  difficulty: Difficulty,
  initials: string
): Promise<SubmitScoreResponse> {
  // 이니셜 검증
  if (!/^[A-Z]{3}$/.test(initials)) {
    throw new Error('Invalid initials: must be 3 uppercase letters');
  }

  // 🚧 로컬 개발 모드: Mock 데이터 반환 (Edge Function이 없을 때)
  if (import.meta.env.DEV) {
    console.warn('⚠️ DEV MODE: Using mock data. Deploy to Supabase to test real API.');

    // 1초 지연으로 실제 API 호출처럼 보이게
    await new Promise(resolve => setTimeout(resolve, 1000));

    return {
      success: true,
      isNewRecord: true,
      previousScore: Math.max(0, score - 100),
      newScore: score,
      rank: Math.floor(Math.random() * 100) + 1,
    };
  }

  // 🚀 프로덕션: Supabase Edge Function 호출 (JWT 자동 포함)
  const { data, error } = await supabase.functions.invoke('leaderboard-submit', {
    body: {
      score,
      difficulty,
      userName: initials,
    },
  });

  if (error) {
    throw new Error(error.message || 'Failed to submit score');
  }

  return data as SubmitScoreResponse;
}

/**
 * 리더보드 조회
 */
export async function getLeaderboard(
  difficulty: Difficulty,
  limit: number = 100
): Promise<LeaderboardResponse> {
  // 🚧 로컬 개발 모드: Mock 데이터 반환
  if (import.meta.env.DEV) {
    console.warn('⚠️ DEV MODE: Using mock leaderboard data. Deploy to Supabase to test real API.');

    // 1초 지연으로 실제 API 호출처럼 보이게
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Mock 리더보드 데이터 생성
    const mockNames = ['AAA', 'BBB', 'CCC', 'DDD', 'EEE', 'FFF', 'GGG', 'HHH', 'III', 'JJJ'];
    const mockLeaderboard: LeaderboardEntry[] = mockNames.slice(0, limit).map((name, index) => ({
      userId: `mock-user-${index + 1}`,
      userName: name,
      score: 1000 - (index * 50),
      rank: index + 1,
    }));

    return {
      success: true,
      difficulty,
      leaderboard: mockLeaderboard,
      currentUserRank: null,
      totalEntries: mockLeaderboard.length,
    };
  }

  // 🚀 프로덕션: Supabase Edge Function 호출 (JWT 자동 포함)
  const { data, error } = await supabase.functions.invoke('leaderboard-top', {
    method: 'GET',
    query: { difficulty, limit: String(limit) },
  } as Parameters<typeof supabase.functions.invoke>[1]);

  if (error) {
    throw new Error(error.message || 'Failed to fetch leaderboard');
  }

  return data as LeaderboardResponse;
}

