    const rainbowPoop = _rainbowPoop as RainbowPoop;
    rainbowPoop.destroy();

    this.updateScore(100);

    if (!this.isFeverTime) {
      const rainbowText = this.add.text(200, 100, '🌈 무지개똥 +100점! 🌈', {
        fontSize: '28px',
        color: '#FF00FF', // A vibrant color for rainbow poop
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 4
      }).setOrigin(0.5);

      this.time.delayedCall(1000, () => {
