        fontSize: '28px',
        color: '#FFC300', // Amber color for topaz
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 4
      }).setOrigin(0.5);

      this.time.delayedCall(1000, () => {
        topazText.destroy();
      });
