    JSON.stringify({ error: 'Invalid score' }),
    { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
  );
}

// 점수 검증 (verification 데이터가 있을 때만)
if (verification) {
  const {
    gameStartTime,
    gameEndTime,
    goldCollected = 0,
    diamondCollected = 0,
    topazCollected = 0,
    rainbowCollected = 0,
  } = verification;

  // 보너스 점수 계산
  const bonusScore =
    goldCollected * 20 +
    diamondCollected * 40 +
    topazCollected * 80 +
    rainbowCollected * 100;

  // 기본 점수 (시간 기반)
  const baseScore = score - bonusScore;

  if (baseScore < 0) {
    return new Response(
      JSON.stringify({ error: 'Score verification failed: invalid bonus count' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  // 아이템 개수 교차 검증 (기본 점수 대비 최대 수집 가능 개수)
  if (goldCollected > Math.floor(baseScore / 40) + 2) { // +2 여유
    return new Response(
      JSON.stringify({ error: 'Score verification failed: too many gold poops' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
  if (diamondCollected > Math.floor(baseScore / 100) + 2) {
    return new Response(
      JSON.stringify({ error: 'Score verification failed: too many diamond poops' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  // 플레이 시간 검증 (기본 점수 × 100ms = 최소 예상 시간)
  const playDuration = gameEndTime - gameStartTime;
  const expectedMinDuration = baseScore * 100; // ms
  const TOLERANCE = 0.6; // 40% 여유 (네트워크/브라우저 지연 고려)

  if (playDuration < expectedMinDuration * TOLERANCE) {
    return new Response(
      JSON.stringify({ error: 'Score verification failed: play time too short' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
}

