  16→
  17→export default class GameScene extends Phaser.Scene {
  18→  private player!: Player;
  19→  private poops!: Phaser.Physics.Arcade.Group;
  20→  private goldPoops!: Phaser.Physics.Arcade.Group;
  21→  private diamondPoops!: Phaser.Physics.Arcade.Group;
