 439→  update() {
 440→    if (!this.gameOver) {
 441→      this.player.update();
 442→
 443→      const now = Date.now();
 444→
 445→      // 레이어 1: Date.now() 기반 점수 계산 (timeScale 조작 무력화)
 446→      const elapsed = now - this.lastScoreTime;
 447→      if (elapsed >= 100) {
 448→        const points = Math.floor(elapsed / 100);
 449→        this.lastScoreTime = now - (elapsed % 100); // 나머지 시간 이월
 450→        this.updateScore(points);
 451→      }
 452→
 453→      // 레이어 2: timeScale 이상 감지 (5초마다 체크)
 454→      if (now - this.lastCheatCheckTime >= 5000) {
 455→        const realElapsed = now - this.gameStartTime;
 456→        const gameElapsed = this.time.now - this.phaserStartTime; // 이번 게임의 Phaser 경과 시간
 457→        const ratio = gameElapsed / realElapsed;
 458→
 459→        // 정상 비율은 ~1.0, 0.8 미만이면 게임 속도가 80% 이하 → 조작 의심
 460→        // rAF timestamp 조작 (time * 0.5) 등을 감지
 461→        if (ratio < 0.8) {
 462→          console.warn('[Anti-cheat] timeScale 조작 감지:', ratio.toFixed(2));
 463→          this.handleCheatDetected();
 464→          return;
 465→        }
 466→        this.lastCheatCheckTime = now;
 467→      }
 468→    }
 469→  }
