 491→  private spawnPoop() {
 492→    if (this.gameOver) return;
 493→
 494→    // 난이도에 따른 개수만큼 생성 (각각 다른 높이에서)
 495→    const poopCount = this.difficultyConfig.poopCount;
 496→    for (let i = 0; i < poopCount; i++) {
 497→      // 💩이 화면 전체에서 생성되도록 (💩 크기 15를 고려해서 양쪽 여유)
 498→      const x = Phaser.Math.Between(15, 385);
 499→      const y = Phaser.Math.Between(-200, -20);
 500→      const poop = new Poop(this, x, y, this.difficultyLevel, this.difficulty);
 501→      this.poops.add(poop, true);
 502→
 503→      // 명시적으로 velocity 설정 (그룹 추가 후)
 504→      if (poop.body) {
 505→        // 난이도 기본 속도 + 시간에 따른 증가
 506→        const fallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * 40);
 507→        poop.body.velocity.y = fallSpeed;
 508→      }
 509→    }
 510→
 511→  }
