 699→  /**
 700→   * 점수가 증가하는 동안 건너뛴 생성 포인트를 확인하고 생성
 701→   * @param oldScore 이전 점수
 702→   * @param newScore 새 점수
 703→   */
 704→  private checkMissedSpawnPoints(oldScore: number, newScore: number) {
 705→    // 40점 단위로 금똥 생성 체크
 706→    for (let score = oldScore + 1; score <= newScore; score++) {
 707→      // 피버 타임 체크
 708→      this.checkFeverTime(score);
 709→
 710→      // 피버 타임 중이 아닐 때만 일반 금똥/다이아똥/토파즈똥 생성
 711→      if (!this.isFeverTime) {
 712→        // 40점마다 금똥 생성 (40, 80, 120, 160, ...)
 713→        if (score % 40 === 0 && score > this.lastGoldPoopScore) {
 714→          this.spawnGoldPoop();
 715→          this.lastGoldPoopScore = score;
 716→        }
 717→
 718→        // 100점마다 다이아똥 생성 (100, 200, 300, ...)
 719→        if (score % 100 === 0 && score > this.lastDiamondPoopScore) {
 720→          this.spawnDiamondPoop();
 721→          this.lastDiamondPoopScore = score;
 722→        }
 723→
 724→        // 160점마다 토파즈똥 생성 (160, 320, 480, ...)
 725→        if (score % 180 === 0 && score > this.lastTopazPoopScore) {
 726→          this.spawnTopazPoop();
 727→          this.lastTopazPoopScore = score;
 728→        }
 729→
 730→        // 광부 캐릭터 선택 시 100점마다 무지개똥 생성 (100, 200, 300, ...)
 731→        if (this.isMinerPlayer && score % 200 === 0 && score > this.lastRainbowPoopScore) {
 732→          this.spawnRainbowPoop();
 733→          this.lastRainbowPoopScore = score;
 734→        }
 735→      }
 736→    }
 737→  }
