1053→    // 2. 금똥/다이아똥 랜덤 생성 (피버 타임 속도 배수 적용)
1054→    for (let i = 0; i < FEVER_TIME_CONFIG.bonusPoopCount; i++) {
1055→      const x = Phaser.Math.Between(50, 350);
1056→      const y = Phaser.Math.Between(-200, -50);
1057→
1058→      // 50% 확률로 금똥 또는 다이아똥 결정
1059→      const isGold = Math.random() < 0.5;
1060→
1061→      if (isGold) {
1062→        const goldPoop = new GoldPoop(this, x, y);
1063→        this.goldPoops.add(goldPoop, true);
1064→        if (goldPoop.body) {
1065→          const baseFallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement) - POOP_CONFIG.gold.speedReduction;
1066→          const fallSpeed = baseFallSpeed * FEVER_TIME_CONFIG.speedMultiplier;
1067→          goldPoop.body.velocity.y = fallSpeed;
1068→        }
1069→      } else {
1070→        const diamondPoop = new DiamondPoop(this, x, y);
1071→        this.diamondPoops.add(diamondPoop, true);
1072→        if (diamondPoop.body) {
1073→          const baseFallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement) - POOP_CONFIG.diamond.speedReduction;
1074→          const fallSpeed = baseFallSpeed * FEVER_TIME_CONFIG.speedMultiplier;
1075→          diamondPoop.body.velocity.y = fallSpeed;
1076→        }
1077→      }
1078→    }
1079→  }
