  1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
  2→
  3→const corsHeaders = {
  4→  'Access-Control-Allow-Origin': '*',
  5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  6→};
  7→
  8→Deno.serve(async (req: Request) => {
  9→  // CORS preflight
 10→  if (req.method === 'OPTIONS') {
 11→    return new Response('ok', { headers: corsHeaders });
 12→  }
 13→
 14→  try {
 15→    const { difficulty, limit: limitParam } = await req.json().catch(() => ({}));
 16→    const limit = parseInt(limitParam ?? '100', 10);
 17→
 18→    // 입력 검증
 19→    const validDifficulties = ['easy', 'normal', 'hard', 'extreme'];
 20→    if (!difficulty || !validDifficulties.includes(difficulty)) {
 21→      return new Response(
 22→        JSON.stringify({ error: 'Invalid difficulty' }),
 23→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
 24→      );
 25→    }
 26→
 27→    const safeLimit = Math.min(Math.max(1, limit), 100);
 28→
 29→    // JWT에서 사용자 인증 (선택적 — 비로그인 시에도 랭킹 조회 가능)
 30→    const authHeader = req.headers.get('Authorization');
 31→    let currentUserId: string | null = null;
 32→
 33→    if (authHeader) {
 34→      const supabaseUser = createClient(
 35→        Deno.env.get('SUPABASE_URL') ?? '',
 36→        Deno.env.get('SUPABASE_ANON_KEY') ?? '',
 37→        { global: { headers: { Authorization: authHeader } } }
 38→      );
 39→      const { data: { user } } = await supabaseUser.auth.getUser();
 40→      currentUserId = user?.id ?? null;
 41→    }
 42→
 43→    // Service Role 클라이언트 (profiles JOIN을 위해)
 44→    const supabaseAdmin = createClient(
 45→      Deno.env.get('SUPABASE_URL') ?? '',
 46→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
 47→    );
 48→
 49→    // 리더보드 조회 (profiles와 JOIN하여 이니셜 포함)
 50→    const { data: leaderboard, error: leaderboardError } = await supabaseAdmin
 51→      .from('leaderboard')
 52→      .select(`
 53→        user_id,
 54→        score,
 55→        profiles!inner(initials)
 56→      `)
 57→      .eq('difficulty', difficulty)
 58→      .order('score', { ascending: false })
 59→      .limit(safeLimit);
 60→
 61→    if (leaderboardError) {
 62→      console.error('Leaderboard query error:', leaderboardError);
 63→      return new Response(
 64→        JSON.stringify({ error: 'Failed to fetch leaderboard' }),
 65→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
 66→      );
 67→    }
 68→
 69→    // 응답 형식 변환
 70→    const entries = (leaderboard ?? []).map((entry, index) => ({
 71→      userId: entry.user_id,
 72→      userName: (entry.profiles as { initials: string | null }).initials ?? '???',
 73→      score: entry.score,
 74→      rank: index + 1,
 75→    }));
 76→
 77→    const totalEntries = entries.length;
 78→
 79→    // 현재 유저의 순위 조회
 80→    let currentUserRank: { rank: number; score: number } | null = null;
 81→    if (currentUserId) {
 82→      const { data: userEntry } = await supabaseAdmin
 83→        .from('leaderboard')
 84→        .select('score')
 85→        .eq('user_id', currentUserId)
 86→        .eq('difficulty', difficulty)
 87→        .single();
 88→
 89→      if (userEntry) {
 90→        const { count: higherCount } = await supabaseAdmin
 91→          .from('leaderboard')
 92→          .select('*', { count: 'exact', head: true })
 93→          .eq('difficulty', difficulty)
 94→          .gt('score', userEntry.score);
 95→
 96→        currentUserRank = {
 97→          rank: (higherCount ?? 0) + 1,
 98→          score: userEntry.score,
 99→        };
100→      }
101→    }
102→
103→    return new Response(
104→      JSON.stringify({
105→        success: true,
106→        difficulty,
107→        leaderboard: entries,
108→        currentUserRank,
109→        totalEntries,
110→      }),
111→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
112→    );
113→  } catch (error) {
114→    console.error('Unexpected error:', error);
115→    return new Response(
116→      JSON.stringify({ error: 'Internal server error' }),
117→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
118→    );
119→  }
120→});
