  1→import Phaser from 'phaser';
  2→
  3→export default class Player extends Phaser.Physics.Arcade.Sprite {
  4→  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
  5→  private speed: number;
  6→  private baseSpeed: number; // 기본 속도 저장
  7→  private texturePrefix: string;
  8→  private leftKeyDown: boolean = false;
  9→  private rightKeyDown: boolean = false;
 10→  private readonly onKeyDown: (e: KeyboardEvent) => void;
 11→  private readonly onKeyUp: (e: KeyboardEvent) => void;
 12→
 13→  // 아이템 효과 상태
 14→  private isInvincible: boolean = false;
 15→  private speedBoostActive: boolean = false;
 16→
 17→  // 효과 타이머
 18→  private invincibleTimer?: Phaser.Time.TimerEvent;
 19→  private speedBoostTimer?: Phaser.Time.TimerEvent;
 20→  private rainbowTimer?: Phaser.Time.TimerEvent;
 21→
 22→  constructor(scene: Phaser.Scene, x: number, y: number, speed: number = 300, texturePrefix: string = '') {
 23→    // 기본 텍스처는 front (정면)
 24→    super(scene, x, y, `${texturePrefix}front`);
 25→    this.speed = speed;
 26→    this.baseSpeed = speed; // 기본 속도 저장
 27→    this.texturePrefix = texturePrefix;
 28→
 29→    // 씬에 추가
 30→    scene.add.existing(this);
 31→    scene.physics.add.existing(this);
 32→
 33→    // 캐릭터 크기 설정
 34→    this.setDisplaySize(50, 80);
 35→
 36→    // 히트박스를 몸통 중심부만 (더 작게)
 37→    this.setSize(300, 650);
 38→    this.setOffset(275,250);
 39→
 40→    // 물리 설정
 41→    this.setCollideWorldBounds(true);
 42→    this.setImmovable(true);
 43→
 44→    // Phaser 키보드 입력
 45→    this.cursors = scene.input.keyboard!.createCursorKeys();
 46→
 47→    // window 레벨 키보드 이벤트 (canvas 포커스와 무관하게 동작)
 48→    this.onKeyDown = (e: KeyboardEvent) => {
 49→      if (e.key === 'ArrowLeft') this.leftKeyDown = true;
 50→      if (e.key === 'ArrowRight') this.rightKeyDown = true;
 51→    };
 52→    this.onKeyUp = (e: KeyboardEvent) => {
 53→      if (e.key === 'ArrowLeft') this.leftKeyDown = false;
 54→      if (e.key === 'ArrowRight') this.rightKeyDown = false;
 55→    };
 56→    // capture: true → window capture phase는 이벤트 전파 최우선 단계
 57→    // Vercel Preview 툴바 등 외부 스크립트가 ArrowLeft/Right를 가로채도 우선 실행됨
 58→    window.addEventListener('keydown', this.onKeyDown, { capture: true });
 59→    window.addEventListener('keyup', this.onKeyUp, { capture: true });
 60→
 61→    // 씬 종료 시 이벤트 리스너 정리
 62→    scene.events.once('shutdown', this.removeKeyListeners, this);
 63→    scene.events.once('destroy', this.removeKeyListeners, this);
 64→  }
 65→
 66→  private removeKeyListeners() {
 67→    window.removeEventListener('keydown', this.onKeyDown, { capture: true });
 68→    window.removeEventListener('keyup', this.onKeyUp, { capture: true });
 69→  }
 70→
 71→  update() {
 72→    let isMoving = false;
 73→
 74→    // 좌우 이동 (Phaser 키보드 OR window 레벨 키보드 둘 다 체크)
 75→    if (this.cursors.left.isDown || this.leftKeyDown) {
 76→      this.setVelocityX(-this.speed);
 77→      this.setTexture(`${this.texturePrefix}left`);
 78→      isMoving = true;
 79→    } else if (this.cursors.right.isDown || this.rightKeyDown) {
 80→      this.setVelocityX(this.speed);
 81→      this.setTexture(`${this.texturePrefix}right`);
 82→      isMoving = true;
 83→    } else {
 84→      this.setVelocityX(0);
 85→    }
 86→
 87→    // 터치/마우스 입력 처리 (화면 중앙 기준)
 88→    if (this.scene.input.activePointer.isDown) {
 89→      const pointerX = this.scene.input.activePointer.x;
 90→      const screenCenter = this.scene.cameras.main.width / 2;
 91→
 92→      if (pointerX < screenCenter) {
 93→        this.setVelocityX(-this.speed);
 94→        this.setTexture(`${this.texturePrefix}left`); // 왼쪽 이미지
 95→        isMoving = true;
 96→      } else if (pointerX > screenCenter) {
 97→        this.setVelocityX(this.speed);
 98→        this.setTexture(`${this.texturePrefix}right`); // 오른쪽 이미지
 99→        isMoving = true;
100→      }
101→    }
102→
103→    // 멈춰있을 때는 정면 이미지
104→    if (!isMoving && this.body?.velocity.x === 0) {
105→      this.setTexture(`${this.texturePrefix}front`);
106→    }
107→  }
108→
109→  // 헤르메스 신발 효과: 10초간 속도 2배 증가
110→  activateSpeedBoost(duration: number = 10000) {
111→    // 기존 타이머가 있으면 제거
112→    if (this.speedBoostTimer) {
113→      this.speedBoostTimer.remove();
114→    }
115→
116→    // 속도 증가 (2배)
117→    this.speedBoostActive = true;
118→    this.speed = this.baseSpeed * 2;
119→
120→    // 시각적 피드백: 노란색 틴트
121→    this.setTint(0xffff00);
122→
123→    // 일정 시간 후 원래 속도로 복구
124→    this.speedBoostTimer = this.scene.time.addEvent({
125→      delay: duration,
126→      callback: () => {
127→        this.speedBoostActive = false;
128→        this.speed = this.baseSpeed;
129→        // 무적이 아니면 틴트 제거
130→        if (!this.isInvincible) {
131→          this.clearTint();
132→        } else {
133→          // 무적 효과만 남김
134→          this.setTint(0x00ffff);
135→        }
136→      },
137→      callbackScope: this
138→    });
139→  }
140→
141→  // 무지개 별 효과: 5초간 무적
142→  activateInvincibility(duration: number = 5000) {
143→    // 기존 타이머가 있으면 제거
144→    if (this.invincibleTimer) {
145→      this.invincibleTimer.remove();
146→    }
147→    if (this.rainbowTimer) {
148→      this.rainbowTimer.remove();
149→    }
150→
151→    // 무적 활성화
152→    this.isInvincible = true;
153→
154→    // 무지개 색상 배열 (빨주노초파남보)
155→    const rainbowColors = [
156→      0xff0000, // 빨강
157→      0xff7700, // 주황
158→      0xffff00, // 노랑
159→      0x00ff00, // 초록
160→      0x00ffff, // 하늘
161→      0x0000ff, // 파랑
162→      0xff00ff  // 보라
163→    ];
164→
165→    let colorIndex = 0;
166→
167→    // 무지개 색상 순환 효과 (150ms마다 색상 변경)
168→    this.rainbowTimer = this.scene.time.addEvent({
169→      delay: 150,
170→      callback: () => {
171→        this.setTint(rainbowColors[colorIndex]);
172→        colorIndex = (colorIndex + 1) % rainbowColors.length;
173→      },
174→      callbackScope: this,
175→      loop: true
176→    });
177→
178→    // 일정 시간 후 무적 해제
179→    this.invincibleTimer = this.scene.time.addEvent({
180→      delay: duration,
181→      callback: () => {
182→        this.isInvincible = false;
183→        // 무지개 타이머 정지
184→        if (this.rainbowTimer) {
185→          this.rainbowTimer.remove();
186→          this.rainbowTimer = undefined;
187→        }
188→        // 속도 증가가 아니면 틴트 제거
189→        if (!this.speedBoostActive) {
190→          this.clearTint();
191→        } else {
192→          // 속도 증가 효과만 남김
193→          this.setTint(0xffff00);
194→        }
195→      },
196→      callbackScope: this
197→    });
198→  }
199→
200→  // 무적 상태 확인
201→  getIsInvincible(): boolean {
202→    return this.isInvincible;
203→  }
204→
205→  // 효과 정리 (씬 종료 시)
206→  cleanupEffects() {
207→    if (this.speedBoostTimer) {
208→      this.speedBoostTimer.remove();
209→    }
210→    if (this.invincibleTimer) {
211→      this.invincibleTimer.remove();
212→    }
213→    if (this.rainbowTimer) {
214→      this.rainbowTimer.remove();
215→    }
216→  }
217→}
