    hitbox: 450,
    depth: 100
  },
  destroyOffset: 50
};

import Phaser from 'phaser';

export default class Star extends Phaser.Physics.Arcade.Sprite {
  private fallSpeed: number;
  private static readonly STAR_TEXTURES = [
    'star',
    'star_smile',
    'star_glasses',
    'star_sunglass'
  ];

  constructor(scene: Phaser.Scene, x: number, y: number) {
    // 랜덤하게 별 텍스처 선택
    const randomTexture = Star.STAR_TEXTURES[
      Math.floor(Math.random() * Star.STAR_TEXTURES.length)
    ];

    super(scene, x, y, randomTexture);

    // 원점을 중앙으로 설정
    this.setOrigin(0.5);

    // 낙하 속도 (아이템 모드는 고정 속도)
    this.fallSpeed = 200;

    // 씬에 추가
    scene.add.existing(this);
    scene.physics.add.existing(this);

    // 별 이미지 크기 설정
    this.setDisplaySize(40, 40);

    // 물리 바디가 생성된 후 설정 적용
    const body = this.body as Phaser.Physics.Arcade.Body;
    if (body) {
      // 히트박스 설정
      body.setSize(500, 500);
      body.setCollideWorldBounds(false);
      body.setVelocityY(this.fallSpeed);
    }
  }

  update() {
    // 화면 밖으로 나가면 제거
    if (this.y > this.scene.cameras.main.height + 50) {
      this.destroy();
    }
  }
}

import Phaser from 'phaser';

export default class Item extends Phaser.Physics.Arcade.Sprite {
  private fallSpeed: number;
  private static readonly ITEM_TEXTURES = [
    'hermes_shoes',
    'light_saber',
    'rainbow_star'
  ];

  constructor(scene: Phaser.Scene, x: number, y: number) {
    // 랜덤하게 아이템 텍스처 선택
    const randomTexture = Item.ITEM_TEXTURES[
      Math.floor(Math.random() * Item.ITEM_TEXTURES.length)
    ];

    super(scene, x, y, randomTexture);

    // 원점을 중앙으로 설정
    this.setOrigin(0.5);

    // 낙하 속도 (별보다 느리게)
    this.fallSpeed = 150;

    // 씬에 추가
    scene.add.existing(this);
    scene.physics.add.existing(this);

    // 아이템 이미지 크기 설정
    this.setDisplaySize(40, 40);

    // 물리 바디가 생성된 후 설정 적용
    const body = this.body as Phaser.Physics.Arcade.Body;
    if (body) {
      // 히트박스 설정 (아이템은 획득하기 쉽게 작게)
      body.setSize(300, 300);
      body.setCollideWorldBounds(false);
      body.setVelocityY(this.fallSpeed);
    }
  }

  update() {
    // 화면 밖으로 나가면 제거
    if (this.y > this.scene.cameras.main.height + 50) {
      this.destroy();
    }
  }
}

import Phaser from 'phaser';
import ModeSelectScene from './scenes/ModeSelectScene';
import DifficultySelectScene from './scenes/DifficultySelectScene';
import GameScene from './scenes/GameScene';
import LeaderboardScene from './scenes/LeaderboardScene';
import ReleaseNotesScene from './scenes/ReleaseNotesScene';
import { ensureLoggedIn } from './utils/auth';
import './style.css';

const config: Phaser.Types.Core.GameConfig = {
  type: Phaser.AUTO,
  width: 400,
  height: 600,
  parent: 'game-container',
  backgroundColor: '#87CEEB',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0, x: 0 },
      debug: false,
      fixedStep: false
    }
  },
  scene: [ModeSelectScene, DifficultySelectScene, GameScene, LeaderboardScene, ReleaseNotesScene],
  scale: {
    mode: Phaser.Scale.FIT,
    autoCenter: Phaser.Scale.CENTER_BOTH
  },
  render: {
    antialias: true,
    roundPixels: false
  },
  fps: {
    // target: 60,
    smoothStep: false
  }
};

// 로그인은 백그라운드에서 진행 (Phaser 게임 생성을 지연시키지 않음)
// ensureLoggedIn()을 await하면 캔버스가 비동기 컨텍스트에서 생성되어
// 브라우저가 키보드 포커스를 정상적으로 할당하지 않는 문제 발생
ensureLoggedIn().catch(error => {
  console.error('로그인 초기화 실패:', error);
});

// 게임 인스턴스는 동기적으로 즉시 생성 (키보드 입력 정상 동작 보장)
new Phaser.Game(config);

