if (window.game) {
     // 게임 객체가 노출된 경우
     game.speed = 1; 
     game.gravity = 0.5;
 } else {
     // 방법 B: 시간의 흐름을 느리게 만들기 (setInterval/setTimeout 가로채기)
     // 이 코드는 이미 실행 중인 게임의 물리 엔진 속도를 늦출 때 효과적입니다.
     const originalRequestAnimationFrame = window.requestAnimationFrame;
     window.requestAnimationFrame = function(callback) {
         return originalRequestAnimationFrame(function(time) {
             // 시간 흐름을 0.5배로 조작 (값이 작을수록 느려짐)
             callback(time * 0.5); 
         });
     };
     console.log("시간의 흐름이 느려졌습니다.");
 } 이거 callback(time * 0.8); 이거로 수정을 하고 했을 땐 또 안먹히는데 치트 방지가.

