      accentColor = 0xFFD700; bgColor = 0x332200; rankColor = '#FFD700'; scoreColor = '#FFD700';
    } else if (entry.rank === 2) {
      accentColor = 0xC0C0C0; bgColor = 0x222233; rankColor = '#C0C0C0'; scoreColor = '#C0C0C0';
    } else if (entry.rank === 3) {
      accentColor = 0xCD7F32; bgColor = 0x221a00; rankColor = '#CD7F32'; scoreColor = '#CD7F32';
    }

