    const rankText = this.add.text(46, y - 2, rankLabel, {
      fontSize: entry.rank <= 3 ? '22px' : '18px',
      color: rankColor,
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 3
    }).setOrigin(0.5, 0.5);
    this.leaderboardObjects.push(rankText);

    // 캐릭터 아이콘
    const charType = entry.characterType ?? 'chibi';
    const iconKey = LeaderboardScene.CHARACTER_ICON_MAP[charType] ?? 'chibi_front';
    if (this.textures.exists(iconKey)) {
      const icon = this.add.image(98, y - 2, iconKey);
      icon.setDisplaySize(30, 40);
      this.leaderboardObjects.push(icon);
    }

    // 이름
    const nameText = this.add.text(120, y - 2, entry.userName, {
      fontSize: '17px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 3
    }).setOrigin(0, 0.5);
    this.leaderboardObjects.push(nameText);

    // 점수
    const scoreText = this.add.text(378, y - 2, entry.score.toLocaleString(), {
      fontSize: '17px',
      color: scoreColor,
      fontStyle: 'bold',
      fontFamily: 'monospace',
      stroke: '#000',
      strokeThickness: 3
    }).setOrigin(1, 0.5);
    this.leaderboardObjects.push(scoreText);
  });
}

