import Phaser from 'phaser';
import { Difficulty, Difficulty as DifficultyEnum } from '../types/GameMode';
import { getLeaderboard, type LeaderboardEntry } from '../utils/leaderboard';

export default class LeaderboardScene extends Phaser.Scene {
  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
  private leaderboardData: LeaderboardEntry[] = [];
  private leaderboardObjects: Phaser.GameObjects.GameObject[] = [];

  private static readonly CHARACTER_ICON_MAP: Record<string, string> = {
    chibi: 'chibi_front',
    miner: 'miner_front',
    maehwa: 'maehwa_front',
    astronaut: 'astronaut_front'
  };
  private loadingText?: Phaser.GameObjects.Text;
  private errorText?: Phaser.GameObjects.Text;
  private currentRequestId: number = 0; // 요청 추적용 ID

  constructor() {
    super('LeaderboardScene');
  }

  init() {
    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
    if (last) {
      this.selectedDifficulty = last;
    }
  }

  preload() {
    // 배경 이미지 로드 (캐시 확인으로 중복 로딩 방지)
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
    // 캐릭터 아이콘 로드 (캐시 확인)
    const characters = ['chibi', 'miner', 'maehwa', 'astronaut'];
    characters.forEach(char => {
      const key = `${char}_front`;
      if (!this.textures.exists(key)) {
        this.load.image(key, `assets/players/${key}.webp`);
      }
    });
  }

  create() {
    // 배경 이미지 추가
    const background = this.add.image(200, 300, 'background2');
    background.setDisplaySize(400, 600);

    // 타이틀
    this.add.text(200, 40, '🏆 랭킹보드 🏆', {
      fontSize: '28px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5
    }).setOrigin(0.5);

    // 난이도 선택 버튼들
    this.createDifficultyButtons();

    // 랭킹 표시 영역 (초기 로딩)
    this.loadingText = this.add.text(200, 300, '로딩 중...', {
      fontSize: '20px',
      color: '#fff',
      stroke: '#000',
      strokeThickness: 3
    }).setOrigin(0.5);

    // 뒤로가기 버튼
    this.createBackButton();

    // 초기 데이터 로드
    this.loadLeaderboard();
  }

  private createDifficultyButtons() {
    const difficulties: Difficulty[] = [
      DifficultyEnum.EASY,
      DifficultyEnum.NORMAL,
      DifficultyEnum.HARD,
      DifficultyEnum.EXTREME
    ];

    const buttonWidth = 80;
    const spacing = 90;
    const startX = 200 - (spacing * 1.5);
    const y = 95;

    difficulties.forEach((difficulty, index) => {
      const x = startX + (index * spacing);
      const isSelected = difficulty === this.selectedDifficulty;

      const button = this.add.rectangle(
        x,
        y,
        buttonWidth,
        35,
        isSelected ? 0xffff99 : 0xffffff,
        1
      );
      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);

      this.add.text(x, y, difficulty, {
        fontSize: '12px',
        color: '#000',
        fontStyle: 'bold'
      }).setOrigin(0.5);

      button.setInteractive({ useHandCursor: true });

      button.on('pointerover', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffcc);
        }
      });

      button.on('pointerout', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffff);
        }
      });

      button.on('pointerdown', () => {
        this.selectDifficulty(difficulty);
      });
    });
  }

  private selectDifficulty(difficulty: Difficulty) {
    // 같은 난이도면 무시
    if (this.selectedDifficulty === difficulty) {
      return;
    }

    this.selectedDifficulty = difficulty;

    // 모든 버튼 스타일 재설정
    this.children.list.forEach((child) => {
      if (child instanceof Phaser.GameObjects.Rectangle && child.y === 95) {
        const index = Math.floor((child.x - 20) / 90);
        const difficulties = [DifficultyEnum.EASY, DifficultyEnum.NORMAL, DifficultyEnum.HARD, DifficultyEnum.EXTREME];
        const isSelected = difficulties[index] === difficulty;

        child.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
        child.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
      }
    });

    // 새로운 난이도 데이터 로드
    this.loadLeaderboard();
  }

  private async loadLeaderboard() {
    // 요청 ID 증가 (새로운 요청 시작)
    this.currentRequestId++;
    const requestId = this.currentRequestId;

    // 기존 랭킹 오브젝트 제거 (텍스트 + 아이콘)
    this.leaderboardObjects.forEach(obj => obj.destroy());
    this.leaderboardObjects = [];

    if (this.errorText) {
      this.errorText.destroy();
      this.errorText = undefined;
    }

    // 로딩 표시
    if (!this.loadingText) {
      this.loadingText = this.add.text(200, 300, '로딩 중...', {
        fontSize: '20px',
        color: '#fff',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5);
    } else {
      this.loadingText.setVisible(true);
    }

    try {
      const response = await getLeaderboard(this.selectedDifficulty, 10);

      // 응답이 도착했을 때 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
        return;
      }

      this.leaderboardData = response.leaderboard;

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.displayLeaderboard();
    } catch (error) {
      // 에러가 발생했을 때도 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
        return;
      }

      console.error('Failed to load leaderboard:', error);

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.errorText = this.add.text(200, 300, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
        fontSize: '16px',
        color: '#ff6666',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
    }
  }

  private displayLeaderboard() {
    const startY = 140;
    const rowHeight = 44;
    const rowWidth = 370;

    // 헤더
    const headerY = startY + 10;
    const headers = [
      { text: '순위', x: 35, originX: 0.5 },
      { text: '이름', x: 145, originX: 0 },
      { text: '점수', x: 375, originX: 1 },
    ];
    headers.forEach(({ text, x, originX }) => {
      const t = this.add.text(x, headerY, text, {
        fontSize: '15px',
        color: '#ffff00',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 4
      }).setOrigin(originX, 0.5);
      this.leaderboardObjects.push(t);
    });

    // 데이터 없음
    if (this.leaderboardData.length === 0) {
      const noDataText = this.add.text(200, startY + 80, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
        fontSize: '18px',
        color: '#ccc',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
      this.leaderboardObjects.push(noDataText);
      return;
    }

    this.leaderboardData.forEach((entry, index) => {
      const y = startY + 35 + (index * rowHeight);

      // 순위별 색상
      let rankColor = '#ffffff';
      let bgAlpha = 0.25;
      if (entry.rank === 1) { rankColor = '#FFD700'; bgAlpha = 0.4; }
      else if (entry.rank === 2) { rankColor = '#C0C0C0'; bgAlpha = 0.35; }
      else if (entry.rank === 3) { rankColor = '#CD7F32'; bgAlpha = 0.3; }

      // 행 배경
      const bg = this.add.rectangle(200, y, rowWidth, rowHeight - 4, 0x000000, bgAlpha);
      bg.setStrokeStyle(1, 0xffffff, 0.15);
      this.leaderboardObjects.push(bg);

      // 순위
      const rankText = this.add.text(35, y, `${entry.rank}`, {
        fontSize: '18px',
        color: rankColor,
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 4
      }).setOrigin(0.5, 0.5);
      this.leaderboardObjects.push(rankText);

      // 캐릭터 아이콘
      const charType = entry.characterType ?? 'chibi';
      const iconKey = LeaderboardScene.CHARACTER_ICON_MAP[charType] ?? 'chibi_front';
      if (this.textures.exists(iconKey)) {
        const icon = this.add.image(105, y, iconKey);
        icon.setDisplaySize(28, 38);
        this.leaderboardObjects.push(icon);
      }

      // 이름
      const nameText = this.add.text(125, y, entry.userName, {
        fontSize: '16px',
        color: '#ffffff',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0, 0.5);
      this.leaderboardObjects.push(nameText);

      // 점수
      const scoreText = this.add.text(375, y, entry.score.toLocaleString(), {
        fontSize: '16px',
        color: rankColor,
        fontStyle: 'bold',
        fontFamily: 'monospace',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(1, 0.5);
      this.leaderboardObjects.push(scoreText);
    });
  }

  private createBackButton() {
    const button = this.add.rectangle(200, 560, 150, 40, 0xffffff, 1);
    button.setStrokeStyle(3, 0x000000);

    const text = this.add.text(200, 560, '← 뒤로가기', {
      fontSize: '18px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });

    const elements = [button, text];
    elements.forEach(element => {
      element.on('pointerover', () => {
        button.setFillStyle(0xffff99);
      });

      element.on('pointerout', () => {
        button.setFillStyle(0xffffff);
      });

      element.on('pointerdown', () => {
        this.scene.start('ModeSelectScene');
      });
    });
  }
}

