      duration: 300,
      yoyo: true,
      repeat: -1,
    });

    this.input.once('pointerdown', () => {
      this.scene.start('ModeSelectScene');
    });
  }
}

import Phaser from 'phaser';

// 캐릭터별 등급 색상
const RARITY_COLORS: Record<string, number> = {
  chibi: 0xffffff,      // 일반 - 흰색
  miner: 0x4488ff,      // 희귀 - 파란색 (16%)
  maehwa: 0xaa44ff,     // 영웅 - 보라색 (4%)
  astronaut: 0xffdd00,  // 전설 - 금색
};

const CHARACTER_NAMES: Record<string, string> = {
  chibi: '치비',
  miner: '광부',
  maehwa: '매화검수',
  astronaut: '우주비행사',
};

export default class GachaScene extends Phaser.Scene {
  private characterType: string = 'chibi';

  constructor() {
    super('GachaScene');
  }

  init(data: { characterType?: string }) {
    this.characterType = data.characterType ?? 'chibi';
  }

  preload() {
    // 캐릭터 이미지 (이미 캐시에 있을 수 있으므로 체크)
    const types = ['chibi', 'miner', 'maehwa', 'astronaut'];
    types.forEach(type => {
      const key = `${type}_front`;
      if (!this.textures.exists(key)) {
        this.load.image(key, `assets/players/${type}_front.webp`);
      }
    });
  }

  create() {
    // 검은 배경으로 시작
    const bg = this.add.rectangle(200, 300, 400, 600, 0x000000);
    bg.setAlpha(1);

    const rarityColor = RARITY_COLORS[this.characterType] ?? 0xffffff;
    const characterName = CHARACTER_NAMES[this.characterType] ?? this.characterType;

    // 빛 링 (배경 원형 글로우)
    const glowRing = this.add.circle(200, 280, 140, rarityColor, 0.15);
    glowRing.setAlpha(0);

    // 빛 줄기들 (방사형 라인)
    const rays = this.createRays(rarityColor);
    rays.forEach(r => r.setAlpha(0));

    // 캐릭터 스프라이트 (실루엣으로 시작)
    const charKey = `${this.characterType}_front`;
    const character = this.add.image(200, 250, charKey);
    character.setDisplaySize(180, 240);
    character.setTint(0x000000); // 실루엣
    character.setAlpha(0);
    character.setScale(0.5);

    // 등급 색상 플래시 오버레이
    const flash = this.add.rectangle(200, 300, 400, 600, rarityColor);
    flash.setAlpha(0);

    // 캐릭터 이름 텍스트
    const nameText = this.add.text(200, 440, characterName, {
      fontSize: '32px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 6,
    }).setOrigin(0.5);
    nameText.setAlpha(0);

    // 등급 텍스트
    const rarityLabel = this.getRarityLabel(this.characterType);
    const rarityText = this.add.text(200, 480, rarityLabel.text, {
      fontSize: '18px',
      color: rarityLabel.color,
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 4,
    }).setOrigin(0.5);
    rarityText.setAlpha(0);

    // 탭하여 건너뛰기 텍스트
    const skipText = this.add.text(200, 560, '탭하여 건너뛰기', {
      fontSize: '14px',
      color: '#888888',
    }).setOrigin(0.5);

    // 탭으로 건너뛰기
    this.input.once('pointerdown', () => {
      this.skipToEnd(character, nameText, rarityText, rarityColor, skipText);
    });

    // 5초 연출 시작
    this.playAnimation(
      bg, glowRing, rays, character, flash,
      nameText, rarityText, rarityColor, skipText
    );
  }

  private playAnimation(
    bg: Phaser.GameObjects.Rectangle,
    glowRing: Phaser.GameObjects.Arc,
    rays: Phaser.GameObjects.Rectangle[],
    character: Phaser.GameObjects.Image,
    flash: Phaser.GameObjects.Rectangle,
    nameText: Phaser.GameObjects.Text,
    rarityText: Phaser.GameObjects.Text,
    rarityColor: number,
    skipText: Phaser.GameObjects.Text,
  ) {
    // ── 1막 (0.0 ~ 0.8s): 배경에 빛이 스며들기 ──────────────────
    this.tweens.add({
      targets: bg,
      fillColor: { from: 0x000000, to: 0x111133 },
      duration: 800,
      ease: 'Sine.easeIn',
    });

    // 빛 링 페이드인 + 회전
    this.time.delayedCall(200, () => {
      this.tweens.add({
        targets: glowRing,
        alpha: { from: 0, to: 1 },
        scaleX: { from: 0.3, to: 1 },
        scaleY: { from: 0.3, to: 1 },
        duration: 600,
        ease: 'Back.easeOut',
      });
    });

    // ── 2막 (0.8 ~ 1.8s): 등급 색상 폭발 ────────────────────────
    this.time.delayedCall(800, () => {
      // 빛 줄기 등장
      rays.forEach((ray, i) => {
        this.time.delayedCall(i * 30, () => {
          this.tweens.add({
            targets: ray,
            alpha: { from: 0, to: 0.7 },
            scaleY: { from: 0, to: 1 },
            duration: 300,
            ease: 'Power2',
          });
        });
      });

      // 전체 화면 색상 플래시
      this.time.delayedCall(200, () => {
        this.tweens.add({
          targets: flash,
          alpha: { from: 0.7, to: 0 },
          duration: 600,
          ease: 'Power2.easeOut',
        });
      });

      // 빛 링 펄스
      this.tweens.add({
        targets: glowRing,
        scaleX: 1.3,
        scaleY: 1.3,
        alpha: 0.8,
        duration: 400,
        yoyo: true,
        ease: 'Sine.easeInOut',
      });
    });

    // ── 3막 (1.8 ~ 3.0s): 실루엣 → 컬러 reveal ──────────────────
    this.time.delayedCall(1800, () => {
      // 캐릭터 등장 (실루엣, 아래서 올라오며)
      character.setY(320);
      this.tweens.add({
        targets: character,
        alpha: { from: 0, to: 1 },
        y: { from: 320, to: 250 },
        scale: { from: 0.5, to: 1 },
        duration: 500,
        ease: 'Back.easeOut',
      });

      // 실루엣 → 컬러 전환 (0.5s 후)
      this.time.delayedCall(500, () => {
        // 짧은 화이트 플래시
        const whiteFlash = this.add.rectangle(200, 300, 400, 600, 0xffffff);
        this.tweens.add({
          targets: whiteFlash,
          alpha: { from: 0.9, to: 0 },
          duration: 400,
          ease: 'Power3.easeOut',
          onComplete: () => whiteFlash.destroy(),
        });

        // 틴트 제거 (컬러 reveal)
        this.tweens.addCounter({
          from: 0,
          to: 255,
          duration: 400,
          ease: 'Power2',
          onUpdate: (tween) => {
            const v = Math.floor(tween.getValue() ?? 0);
            const gray = Phaser.Display.Color.GetColor(v, v, v);
            character.setTint(gray);
          },
          onComplete: () => {
            character.clearTint();
          },
        });
      });

      // 빛 줄기 회전 애니메이션
      this.tweens.add({
        targets: rays,
        angle: '+=45',
        duration: 1200,
        ease: 'Linear',
      });
    });

    // ── 4막 (3.0 ~ 4.2s): 이름 텍스트 등장 ──────────────────────
    this.time.delayedCall(3000, () => {
      // 캐릭터 살짝 튀기기
      this.tweens.add({
        targets: character,
        y: { from: 250, to: 235 },
        duration: 200,
        yoyo: true,
        ease: 'Bounce.easeOut',
      });

      // 이름 텍스트 슬라이드인
      nameText.setY(470);
      this.tweens.add({
        targets: nameText,
        alpha: { from: 0, to: 1 },
        y: { from: 470, to: 440 },
        duration: 400,
        ease: 'Back.easeOut',
      });

      // 등급 텍스트
      this.time.delayedCall(200, () => {
        this.tweens.add({
          targets: rarityText,
          alpha: { from: 0, to: 1 },
          duration: 300,
          ease: 'Power2',
        });
      });

      // 파티클 효과 (별 모양 대신 원형)
      this.spawnParticles(rarityColor);
    });

    // ── 5막 (4.2 ~ 5.0s): 마무리 + 탭 유도 ──────────────────────
    this.time.delayedCall(4200, () => {
      // 빛 줄기 페이드아웃
      this.tweens.add({
        targets: rays,
        alpha: 0,
        duration: 600,
        ease: 'Power2',
      });

      // 빛 링 페이드아웃
      this.tweens.add({
        targets: glowRing,
        alpha: 0,
        duration: 600,
      });

      // 탭 건너뛰기 텍스트 → "탭하여 확인" 으로 변경
      skipText.setText('탭하여 계속');
      skipText.setColor('#ffffff');
      this.tweens.add({
        targets: skipText,
        alpha: { from: 0.5, to: 1 },
        duration: 300,
        yoyo: true,
        repeat: -1,
      });
    });

    // 5초 후 자동으로 input 활성화 (이미 눌렀으면 무시)
    this.time.delayedCall(5000, () => {
      // 이미 input.once가 소비됐으면 다시 등록
      this.input.off('pointerdown');
      this.input.once('pointerdown', () => {
        this.scene.start('ModeSelectScene');
      });
    });
  }

  private createRays(color: number): Phaser.GameObjects.Rectangle[] {
    const rays: Phaser.GameObjects.Rectangle[] = [];
    const count = 12;

    for (let i = 0; i < count; i++) {
      const angle = (i / count) * 360;
      const ray = this.add.rectangle(200, 280, 8, 280, color, 0.5);
      ray.setOrigin(0.5, 1); // 중심점에서 바깥으로
      ray.setAngle(angle);
      rays.push(ray);
    }

    return rays;
  }

  private spawnParticles(color: number) {
    const hexColor = `#${color.toString(16).padStart(6, '0')}`;

    for (let i = 0; i < 20; i++) {
      const x = Phaser.Math.Between(50, 350);
      const y = Phaser.Math.Between(100, 500);
      const size = Phaser.Math.Between(4, 10);

      const particle = this.add.circle(x, y, size, color, 0.8);
      particle.setAlpha(0);

      this.time.delayedCall(i * 50, () => {
        this.tweens.add({
          targets: particle,
          alpha: { from: 0.8, to: 0 },
          y: y - Phaser.Math.Between(30, 80),
          x: x + Phaser.Math.Between(-20, 20),
          scale: { from: 1, to: 0 },
          duration: Phaser.Math.Between(600, 1200),
          ease: 'Power2.easeOut',
          onComplete: () => particle.destroy(),
        });
      });
    }
  }

  private getRarityLabel(characterType: string): { text: string; color: string } {
    const labels: Record<string, { text: string; color: string }> = {
      chibi: { text: '★ 일반', color: '#cccccc' },
      miner: { text: '★★ 희귀', color: '#4488ff' },
      maehwa: { text: '★★★ 영웅', color: '#cc44ff' },
      astronaut: { text: '★★★★ 전설', color: '#ffdd00' },
    };
    return labels[characterType] ?? { text: '★ 일반', color: '#cccccc' };
  }

  private skipToEnd(
    character: Phaser.GameObjects.Image,
    nameText: Phaser.GameObjects.Text,
    rarityText: Phaser.GameObjects.Text,
    rarityColor: number,
    skipText: Phaser.GameObjects.Text,
  ) {
    // 모든 트윈 중지
    this.tweens.killAll();
    this.time.removeAllEvents();

    // 최종 상태로 즉시 세팅
    character.clearTint();
    character.setAlpha(1);
    character.setScale(1);
    character.setY(250);

    nameText.setAlpha(1);
    nameText.setY(440);
    rarityText.setAlpha(1);

    this.spawnParticles(rarityColor);

    skipText.setText('탭하여 계속');
    skipText.setColor('#ffffff');
    this.tweens.add({
      targets: skipText,
      alpha: { from: 0.5, to: 1 },
      duration: 300,
      yoyo: true,
      repeat: -1,
    });

    this.input.once('pointerdown', () => {
      this.scene.start('ModeSelectScene');
    });
  }
}

import Phaser from 'phaser';
import { GameMode, GAME_MODES, type GameModeConfig } from '../types/GameMode';

export default class ModeSelectScene extends Phaser.Scene {
  constructor() {
    super('ModeSelectScene');
  }

  preload() {
    // 배경 이미지 로드 (캐시 확인으로 중복 로딩 방지)
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
    if (!this.textures.exists('title')) {
      this.load.image('title', 'assets/title.webp');
    }
  }

  create() {
    // 배경 이미지 추가
    const background = this.add.image(200, 300, 'background2');
    // 배경을 화면에 맞게 조정
    background.setDisplaySize(400, 600);

    // 타이틀 이미지 추가
    const title = this.add.image(200, 90, 'title');
    title.setScale(0.4); // 크기 조정

    this.add.text(200, 190, '모드를 선택하세요', {
      fontSize: '20px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4
    }).setOrigin(0.5);

    const startY = 250;
    const buttonSpacing = 120;

    GAME_MODES.forEach((modeConfig: GameModeConfig, index: number) => {
      const y = startY + (index * buttonSpacing);
      this.createModeButton(modeConfig, 200, y);
    });

    // 랭킹보드 버튼 추가
    this.createLeaderboardButton();

    // 릴리즈 노트 링크
    this.createReleaseNotesLink();
  }

  private createModeButton(modeConfig: GameModeConfig, x: number, y: number) {
    // 가챠 모드는 연출 씬으로 연결 (비활성화 해제)
    const isDisabled = false;

    const button = this.add.rectangle(x, y, 300, 80, isDisabled ? 0xcccccc : 0xffffff, 1);
    button.setStrokeStyle(4, isDisabled ? 0x666666 : 0x000000);

    // 비활성화된 경우 텍스트 3줄, 활성화된 경우 2줄
    const title = this.add.text(x, y - 12, modeConfig.name, {
      fontSize: '24px',
      color: isDisabled ? '#666' : '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    const description = this.add.text(x, y + 18, modeConfig.description, {
      fontSize: '14px',
      color: isDisabled ? '#888' : '#333',
      align: 'center'
    }).setOrigin(0.5);

    // 비활성화된 경우 인터랙션 없음
    if (isDisabled) {
      // "준비 중" 라벨 추가
      // this.add.text(x, y + 32, '준비 중', {
      //   fontSize: '12px',
      //   color: '#999',
      //   fontStyle: 'italic'
      // }).setOrigin(0.5);
      return; // 여기서 종료, 클릭 이벤트 없음
    }

    // 활성화된 버튼만 인터랙션 추가
    button.setInteractive({ useHandCursor: true });
    title.setInteractive({ useHandCursor: true });
    description.setInteractive({ useHandCursor: true });

    const elements = [button, title, description];
    elements.forEach(element => {
      element.on('pointerover', () => {
        button.setFillStyle(0xffff99);
      });

      element.on('pointerout', () => {
        button.setFillStyle(0xffffff);
      });

      element.on('pointerdown', () => {
        this.startGame(modeConfig.mode);
      });
    });
  }

  private startGame(mode: GameMode) {
    // 클래식 모드일 경우 난이도 선택 화면으로 이동
    if (mode === GameMode.CLASSIC) {
      this.scene.start('DifficultySelectScene', { gameMode: mode });
    } else if (mode === GameMode.GACHA) {
      // 가챠 연출 씬으로 이동 (테스트: chibi 캐릭터)
      this.scene.start('GachaScene', { characterType: 'chibi' });
    } else {
      this.scene.start('GameScene', { gameMode: mode, difficulty: 'HARD' });
    }
  }

  private createReleaseNotesLink() {
    const text = this.add.text(200, 580, '📋 릴리즈 노트', {
      fontSize: '18px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4,
    }).setOrigin(0.5);

    text.setInteractive({ useHandCursor: true });

    text.on('pointerover', () => {
      text.setColor('#FFD700');
    });

    text.on('pointerout', () => {
      text.setColor('#fff');
    });

    text.on('pointerdown', () => {
      this.scene.start('ReleaseNotesScene');
    });
  }

  private createLeaderboardButton() {
    const button = this.add.rectangle(200, 495, 300, 80, 0x4a90e2, 1);
    button.setStrokeStyle(4, 0x2e5c8a);

    const text = this.add.text(200, 495, '🏆 랭킹보기 🏆', {
      fontSize: '24px',
      color: '#fff',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });
    text.setInteractive({ useHandCursor: true });

    const elements = [button, text];
    elements.forEach(element => {
      element.on('pointerover', () => {
        button.setFillStyle(0x5ba3f5);
      });

      element.on('pointerout', () => {
        button.setFillStyle(0x4a90e2);
      });

      element.on('pointerdown', () => {
        this.scene.start('LeaderboardScene');
      });
    });
  }
}

