     1→import Phaser from 'phaser';
     2→import {
     3→  CHARACTERS,
     4→  getOwnedCharacters,
     5→  getSelectedCharacter,
     6→  setSelectedCharacter,
     7→  type CharacterDef,
     8→} from '../utils/character';
     9→
    10→// 그리드 설정
    11→const COLS = 3;
    12→const CARD_W = 100;
    13→const CARD_H = 120;
    14→const GAP_X = 15;
    15→const GAP_Y = 18;
    16→const GRID_LEFT = (400 - (COLS * CARD_W + (COLS - 1) * GAP_X)) / 2; // 35px
    17→const GRID_TOP = 155;
    18→
    19→export default class CharacterSelectScene extends Phaser.Scene {
    20→  private selectedId: string = 'chibi';
    21→  private ownedIds: string[] = [];
    22→  private cardHighlights: Map<string, Phaser.GameObjects.Rectangle> = new Map();
    23→
    24→  constructor() {
    25→    super('CharacterSelectScene');
    26→  }
    27→
    28→  preload() {
    29→    for (const char of CHARACTERS) {
    30→      if (!this.textures.exists(char.imageKey)) {
    31→        this.load.image(char.imageKey, char.imagePath);
    32→      }
    33→    }
    34→  }
    35→
    36→  create() {
    37→    this.selectedId = getSelectedCharacter();
    38→    this.ownedIds = getOwnedCharacters();
    39→    this.cardHighlights.clear();
    40→
    41→    // 배경
    42→    this.add.rectangle(200, 300, 400, 600, 0x111111);
    43→
    44→    // 헤더
    45→    this.add.text(200, 40, '캐릭터 선택', {
    46→      fontSize: '26px',
    47→      color: '#ffffff',
    48→      fontStyle: 'bold',
    49→      stroke: '#000',
    50→      strokeThickness: 4,
    51→    }).setOrigin(0.5);
    52→
    53→    // 선택 중인 캐릭터 표시
    54→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
    55→    this.add.text(200, 80, `현재: ${selectedDef.name}`, {
    56→      fontSize: '16px',
    57→      color: selectedDef.gradeColor,
    58→      stroke: '#000',
    59→      strokeThickness: 3,
    60→    }).setOrigin(0.5);
    61→
    62→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
    63→      fontSize: '13px',
    64→      color: '#888888',
    65→    }).setOrigin(0.5);
    66→
    67→    // 캐릭터 카드 그리드
    68→    CHARACTERS.forEach((char, index) => {
    69→      const col = index % COLS;
    70→      const row = Math.floor(index / COLS);
    71→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
    72→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
    73→      this.createCharacterCard(char, x, y);
    74→    });
    75→
    76→    // 뒤로 가기
    77→    this.createBackButton();
    78→  }
    79→
    80→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
    81→    const isOwned = this.ownedIds.includes(char.id);
    82→    const isSelected = this.selectedId === char.id;
    83→
    84→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
    85→
    86→    // 카드 배경
    87→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
    88→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
    89→
    90→    // 선택 하이라이트 (선택됐으면 밝은 테두리)
    91→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
