    96→
    97→  private addPullButton(x: number, y: number, label: string, cost: string, type: 'single' | 'multi') {
    98→    const btn = this.add.rectangle(x, y, 300, 58, 0x080818)
    99→      .setStrokeStyle(1, 0x00ff41, 0.7)
   100→      .setInteractive({ useHandCursor: true });
