   168→      `> EXECUTE entity_summon(n=${count})`,
   169→      '> Establishing connection...',
   170→    ], 42);
   171→    await this.progressBar(700);
   172→    await this.typeLines([
   173→      '> CONN: OK  [sec-layer bypassed]',
   174→      '> Scanning entity pool...',
   175→    ], 40);
   176→    await this.progressBar(600);
   177→    await this.typeLines([
   178→      '> Anomaly detected in sector 7',
   179→      '> Overriding...',
   180→    ], 42);
   181→    await this.progressBar(800);
   182→    await this.typeLines([
   183→      `> ${count} ENTR${count > 1 ? 'IES' : 'Y'} LOCKED`,
   184→      '> EXTRACTING . . .',
   185→    ], 48);
   186→    await this.sleep(400);
   187→  }
   188→
   189→  private loadCharVideos(ids: string[]): Promise<void> {
   190→    const toLoad = ids.filter(
   191→      id => CHARS_WITH_VIDS.has(id) && !this.cache.video.exists(`vid_${id}`)
   192→    );
   193→    if (toLoad.length === 0) return Promise.resolve();
   194→
   195→    return new Promise(resolve => {
   196→      toLoad.forEach(id => this.load.video(`vid_${id}`, `assets/vids/${id}.mp4`));
   197→      this.load.once(Phaser.Loader.Events.COMPLETE, resolve);
   198→      this.load.once(Phaser.Loader.Events.FILE_LOAD_ERROR, resolve); // 실패해도 진행
   199→      this.load.start();
   200→    });
   201→  }
   202→
   203→  private playCommonVideo(videoType: 'green' | 'red'): Promise<void> {
   204→    return new Promise(resolve => {
   205→      this.clearUI();
   206→      this.add.rectangle(200, 300, 400, 600, 0x000000);
   207→
   208→      const key = videoType === 'red' ? 'gatcha_red' : 'gatcha_green';
   209→      if (!this.cache.video.exists(key)) { resolve(); return; }
   210→
   211→      const vid = this.add.video(200, 300, key);
   212→      vid.setDisplaySize(400, 600);
   213→      vid.play(false);
   214→      vid.on('complete', () => { vid.destroy(); resolve(); });
   215→      this.time.delayedCall(12000, resolve); // 12초 failsafe
   216→    });
   217→  }
   218→
   219→  // ═══════════════════════════════════════════════════
   220→  // CHARACTER REVEAL
   221→  // ═══════════════════════════════════════════════════
   222→
   223→  private showNextReveal() {
   224→    if (this.revealIndex >= this.pullResults.length) {
   225→      this.showSummary();
   226→      return;
   227→    }
   228→
   229→    const pulled = this.pullResults[this.revealIndex];
   230→    const def = getCharacterDef(pulled.id);
   231→
   232→    this.clearUI();
   233→    this.add.rectangle(200, 300, 400, 600, 0x000000);
   234→
   235→    const vidKey = `vid_${pulled.id}`;
   236→    if (this.cache.video.exists(vidKey)) {
   237→      const vid = this.add.video(200, 300, vidKey);
   238→      vid.setDisplaySize(400, 600);
   239→      vid.play(false);
   240→
   241→      let proceeded = false;
   242→      const proceed = () => {
   243→        if (proceeded) return;
   244→        proceeded = true;
   245→        this.input.off('pointerdown', proceed);
   246→        if (vid.active) vid.destroy();
   247→        this.showRevealCard(pulled, def);
   248→      };
   249→
   250→      vid.on('complete', proceed);
   251→      this.time.delayedCall(10000, proceed); // failsafe
   252→      this.input.once('pointerdown', proceed); // 탭으로 스킵
   253→    } else {
   254→      this.showRevealCard(pulled, def);
   255→    }
   256→  }
   257→
   258→  private showRevealCard(pulled: PulledCharacter, def: CharacterDef) {
   259→    const gColor = GRADE_COLORS[pulled.grade] ?? 0xffffff;
   260→
   261→    // 배경 글로우
   262→    const glow = this.add.circle(200, 255, 150, gColor, 0.07).setAlpha(0);
   263→    this.tweens.add({
   264→      targets: glow, alpha: 0.12,
   265→      scaleX: { from: 0.3, to: 1.15 }, scaleY: { from: 0.3, to: 1.15 },
   266→      duration: 600, ease: 'Back.easeOut',
