   298→        backgroundColor: '#cc0000', stroke: '#000', strokeThickness: 2,
   299→      }).setOrigin(0.5).setAlpha(0).setScale(0);
   300→      this.tweens.add({
   301→        targets: badge, alpha: 1, scaleX: 1, scaleY: 1,
   302→        duration: 300, ease: 'Back.easeOut', delay: 650,
