   390→
   391→    // 한 번 더 / 메인으로 버튼
   392→    const againBtn = this.add.rectangle(200, 445, 260, 52, 0x080818)
   393→      .setStrokeStyle(1, 0x00ff41).setInteractive({ useHandCursor: true });
   394→    this.add.text(200, 445, '> 한 번 더', {
