   158→
   159→    btn.on('pointerover', () => btn.setStrokeStyle(2.5, accentColor));
   160→    btn.on('pointerout',  () => btn.setStrokeStyle(1.5, accentColor));
   161→    btn.on('pointerdown', () => this.startPull(type));
   162→  }
   163→
   164→  // ═══════════════════════════════════════════════════
   165→  // PULL FLOW
   166→  // ═══════════════════════════════════════════════════
   167→
   168→  private async startPull(type: 'single' | 'multi') {
   169→    const cost = type === 'multi' ? 900 : 100;
   170→    if (this.skorBalance < cost) {
   171→      const errMsg = this.add.text(200, 370, `SKOR 부족  (보유 ${Math.floor(this.skorBalance)} / 필요 ${cost})`, {
   172→        fontSize: '13px', color: '#ff5555',
   173→        stroke: '#000000', strokeThickness: 3,
   174→        backgroundColor: '#00000099',
   175→        padding: { x: 10, y: 5 },
   176→      }).setOrigin(0.5);
   177→      this.time.delayedCall(2200, () => { if (errMsg.active) errMsg.destroy(); });
   178→      return;
   179→    }
   180→
   181→    this.clearUI();
   182→    this.add.rectangle(200, 300, 400, 600, 0x000000);
   183→    this.drawTerminalChrome();
   184→
   185→    const count = type === 'multi' ? 10 : 1;
   186→
   187→    try {
   188→      // 터미널 애니메이션과 서버 호출을 병렬로 실행
   189→      const [result] = await Promise.all([
   190→        gachaPull(type),
   191→        this.runTerminalAnimation(count),
   192→      ]);
   193→
   194→      if (!this.scene.isActive()) return;
   195→
   196→      this.pullResults = result.characters;
   197→      this.remainingSkor = result.remainingSkor;
   198→
   199→      // 신규 캐릭터 localStorage 동기화
   200→      result.characters.filter(c => c.isNew).forEach(c => addOwnedCharacter(c.id));
   201→
   202→      // 캐릭터별 개인 영상 동적 로드
   203→      await this.loadCharVideos(result.characters.map(c => c.id));
   204→
   205→      await this.playCommonVideo(result.video);
   206→
   207→      this.revealIndex = 0;
   208→      this.showNextReveal();
   209→    } catch {
   210→      if (!this.scene.isActive()) return;
   211→      await this.typeLines([
   212→        '> CONNECTION ERROR',
   213→        '> Retrying in 3s...',
   214→      ], 30);
   215→      this.time.delayedCall(3000, () => this.buildLobby());
   216→    }
   217→  }
   218→
   219→  private async runTerminalAnimation(count: number): Promise<void> {
   220→    await this.typeLines([
   221→      `> EXECUTE entity_summon(n=${count})`,
   222→      '> Establishing connection...',
   223→    ], 42);
   224→    await this.progressBar(700);
   225→    await this.typeLines([
   226→      '> CONN: OK  [sec-layer bypassed]',
   227→      '> Scanning entity pool...',
   228→    ], 40);
   229→    await this.progressBar(600);
   230→    await this.typeLines([
   231→      '> Anomaly detected in sector 7',
   232→      '> Overriding...',
   233→    ], 42);
   234→    await this.progressBar(800);
   235→    await this.typeLines([
   236→      `> ${count} ENTR${count > 1 ? 'IES' : 'Y'} LOCKED`,
   237→      '> EXTRACTING . . .',
   238→    ], 48);
   239→    await this.sleep(400);
   240→  }
   241→
   242→  private loadCharVideos(ids: string[]): Promise<void> {
   243→    const toLoad = ids.filter(
   244→      id => CHARS_WITH_VIDS.has(id) && !this.cache.video.exists(`vid_${id}`)
   245→    );
   246→    if (toLoad.length === 0) return Promise.resolve();
   247→
   248→    return new Promise(resolve => {
   249→      toLoad.forEach(id => this.load.video(`vid_${id}`, `assets/vids/${id}.mp4`));
   250→      this.load.once(Phaser.Loader.Events.COMPLETE, resolve);
   251→      this.load.once(Phaser.Loader.Events.FILE_LOAD_ERROR, resolve); // 실패해도 진행
   252→      this.load.start();
   253→    });
   254→  }
   255→
   256→  private playCommonVideo(videoType: 'green' | 'red'): Promise<void> {
   257→    return new Promise(resolve => {
   258→      this.clearUI();
   259→      this.add.rectangle(200, 300, 400, 600, 0x000000);
   260→
   261→      const key = videoType === 'red' ? 'gatcha_red' : 'gatcha_green';
   262→      if (!this.cache.video.exists(key)) { resolve(); return; }
   263→
   264→      const vid = this.add.video(200, 300, key);
   265→      vid.setDisplaySize(400, 600);
   266→      vid.play(false);
   267→      vid.on('complete', () => { vid.destroy(); resolve(); });
   268→      this.time.delayedCall(12000, resolve); // 12초 failsafe
   269→    });
   270→  }
   271→
   272→  // ═══════════════════════════════════════════════════
   273→  // CHARACTER REVEAL
   274→  // ═══════════════════════════════════════════════════
   275→
   276→  private showNextReveal() {
   277→    if (this.revealIndex >= this.pullResults.length) {
   278→      this.showSummary();
   279→      return;
   280→    }
   281→
   282→    const pulled = this.pullResults[this.revealIndex];
   283→    const def = getCharacterDef(pulled.id);
   284→
   285→    this.clearUI();
   286→    this.add.rectangle(200, 300, 400, 600, 0x000000);
   287→
   288→    const vidKey = `vid_${pulled.id}`;
   289→    if (this.cache.video.exists(vidKey)) {
   290→      const vid = this.add.video(200, 300, vidKey);
   291→      vid.setDisplaySize(400, 600);
   292→      vid.play(false);
   293→
   294→      let proceeded = false;
   295→      const proceed = () => {
   296→        if (proceeded) return;
   297→        proceeded = true;
   298→        this.input.off('pointerdown', proceed);
   299→        if (vid.active) vid.destroy();
   300→        this.showRevealCard(pulled, def);
   301→      };
   302→
   303→      vid.on('complete', proceed);
   304→      this.time.delayedCall(10000, proceed); // failsafe
   305→      this.input.once('pointerdown', proceed); // 탭으로 스킵
   306→    } else {
   307→      this.showRevealCard(pulled, def);
   308→    }
   309→  }
   310→
   311→  private showRevealCard(pulled: PulledCharacter, def: CharacterDef) {
   312→    const gColor = GRADE_COLORS[pulled.grade] ?? 0xffffff;
   313→
   314→    // 배경 글로우
   315→    const glow = this.add.circle(200, 255, 150, gColor, 0.07).setAlpha(0);
   316→    this.tweens.add({
   317→      targets: glow, alpha: 0.12,
   318→      scaleX: { from: 0.3, to: 1.15 }, scaleY: { from: 0.3, to: 1.15 },
   319→      duration: 600, ease: 'Back.easeOut',
   320→    });
   321→
   322→    // 캐릭터 이미지
   323→    const img = this.add.image(200, 240, def.imageKey).setAlpha(0);
   324→    img.setDisplaySize(165, 205);
   325→    this.tweens.add({
   326→      targets: img, alpha: 1, y: { from: 268, to: 240 },
   327→      duration: 500, ease: 'Back.easeOut', delay: 150,
   328→    });
   329→
   330→    // 등급 라벨
   331→    const gradeText = this.add.text(200, 388, pulled.grade, {
   332→      fontSize: '18px', color: def.gradeColor, fontStyle: 'bold',
   333→      stroke: '#000', strokeThickness: 4, fontFamily: 'monospace',
   334→    }).setOrigin(0.5).setAlpha(0);
   335→    this.tweens.add({ targets: gradeText, alpha: 1, duration: 300, delay: 400 });
   336→
   337→    // 캐릭터 이름
   338→    const nameText = this.add.text(200, 424, def.name, {
   339→      fontSize: '34px', color: '#ffffff', fontStyle: 'bold',
   340→      stroke: '#000000', strokeThickness: 6,
   341→    }).setOrigin(0.5).setAlpha(0);
   342→    this.tweens.add({
   343→      targets: nameText, alpha: 1, y: { from: 442, to: 424 },
   344→      duration: 400, ease: 'Back.easeOut', delay: 500,
   345→    });
   346→
   347→    // NEW! 배지
   348→    if (pulled.isNew) {
   349→      const badge = this.add.text(325, 145, ' NEW! ', {
   350→        fontSize: '15px', color: '#ffff00', fontStyle: 'bold',
   351→        backgroundColor: '#cc0000', stroke: '#000', strokeThickness: 2,
   352→      }).setOrigin(0.5).setAlpha(0).setScale(0);
   353→      this.tweens.add({
   354→        targets: badge, alpha: 1, scaleX: 1, scaleY: 1,
   355→        duration: 300, ease: 'Back.easeOut', delay: 650,
   356→      });
   357→    }
   358→
   359→    // 탭 안내
   360→    const isLast = this.revealIndex >= this.pullResults.length - 1;
   361→    const hint = isLast
   362→      ? 'TAP → RESULTS'
   363→      : `TAP → NEXT  (${this.revealIndex + 1}/${this.pullResults.length})`;
   364→    const tapHint = this.add.text(200, 562, hint, {
   365→      fontSize: '13px', color: '#555555', fontFamily: 'monospace',
   366→    }).setOrigin(0.5);
   367→    this.tweens.add({
   368→      targets: tapHint, alpha: { from: 0.3, to: 1 }, duration: 600, yoyo: true, repeat: -1,
   369→    });
   370→
   371→    // 탭 진행 (700ms 디바운스)
   372→    this.time.delayedCall(700, () => {
   373→      if (!this.scene.isActive()) return;
   374→
   375→      let advanced = false;
   376→      const advance = () => {
   377→        if (advanced) return;
   378→        advanced = true;
   379→        this.input.off('pointerdown', advance);
   380→        this.tweens.killAll();
   381→        this.time.removeAllEvents();
   382→        this.revealIndex++;
   383→        this.showNextReveal();
   384→      };
   385→
   386→      this.input.on('pointerdown', advance);
   387→
   388→      // 10뽑기는 3.5초 자동 진행
   389→      if (this.pullResults.length > 1) {
   390→        this.time.delayedCall(3500, () => {
   391→          if (this.scene.isActive()) advance();
   392→        });
   393→      }
   394→    });
   395→  }
   396→
   397→  // ═══════════════════════════════════════════════════
   398→  // SUMMARY
   399→  // ═══════════════════════════════════════════════════
   400→
   401→  private showSummary() {
   402→    this.clearUI();
   403→    this.add.rectangle(200, 300, 400, 600, 0x060612);
   404→
   405→    this.add.text(200, 38, '[ EXTRACTION COMPLETE ]', {
   406→      fontSize: '17px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   407→    }).setOrigin(0.5);
   408→
   409→    // 결과 카드 그리드
   410→    const total = this.pullResults.length;
   411→    const cols = Math.min(total, 5);
   412→    const cardW = 64, cardH = 84, gapX = 8, gapY = 12;
   413→    const totalW = cols * cardW + (cols - 1) * gapX;
   414→    const startX = (400 - totalW) / 2 + cardW / 2;
   415→    const startY = total > 5 ? 130 : 175;
   416→
   417→    this.pullResults.forEach((pulled, i) => {
   418→      const def = getCharacterDef(pulled.id);
   419→      const col = i % 5;
   420→      const row = Math.floor(i / 5);
   421→      const x = startX + col * (cardW + gapX);
   422→      const y = startY + row * (cardH + gapY);
   423→      const gColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   424→
   425→      const bg  = this.add.rectangle(x, y, cardW, cardH, 0x111122).setStrokeStyle(1, gColorInt).setAlpha(0);
   426→      const img = this.add.image(x, y - 8, def.imageKey).setDisplaySize(cardW - 8, cardH - 22).setAlpha(0);
   427→      const nm  = this.add.text(x, y + cardH / 2 - 10, def.name, { fontSize: '9px', color: '#cccccc' }).setOrigin(0.5).setAlpha(0);
   428→
   429→      if (pulled.isNew) {
   430→        this.add.text(x + cardW / 2, y - cardH / 2 + 2, 'NEW', {
   431→          fontSize: '8px', color: '#ffff00', backgroundColor: '#aa0000', padding: { x: 2, y: 1 },
   432→        }).setOrigin(1, 0).setAlpha(0);
   433→      }
   434→
   435→      this.tweens.add({ targets: [bg, img, nm], alpha: 1, duration: 200, delay: i * 60 });
   436→    });
   437→
   438→    // 잔여 SKOR
   439→    const skorY = total > 5 ? 350 : 340;
   440→    this.add.text(200, skorY, `> 잔여 SKOR: ${Math.floor(this.remainingSkor)}`, {
   441→      fontSize: '14px', color: '#337733', fontFamily: 'monospace',
   442→    }).setOrigin(0.5);
   443→
   444→    // 한 번 더 / 메인으로 버튼
   445→    const againBtn = this.add.rectangle(200, 445, 260, 52, 0x080818)
   446→      .setStrokeStyle(1, 0x00ff41).setInteractive({ useHandCursor: true });
   447→    this.add.text(200, 445, '> 한 번 더', {
   448→      fontSize: '19px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   449→    }).setOrigin(0.5);
   450→    againBtn.on('pointerover', () => againBtn.setFillStyle(0x081808));
   451→    againBtn.on('pointerout',  () => againBtn.setFillStyle(0x080818));
   452→    againBtn.on('pointerdown', () => this.buildLobby());
   453→
   454→    const mainBtn = this.add.rectangle(200, 525, 260, 52, 0x1a1a1a)
   455→      .setStrokeStyle(1, 0x444444).setInteractive({ useHandCursor: true });
   456→    this.add.text(200, 525, '← 메인으로', {
   457→      fontSize: '19px', color: '#888888', fontStyle: 'bold', fontFamily: 'monospace',
   458→    }).setOrigin(0.5);
   459→    mainBtn.on('pointerover', () => mainBtn.setFillStyle(0x282828));
   460→    mainBtn.on('pointerout',  () => mainBtn.setFillStyle(0x1a1a1a));
   461→    mainBtn.on('pointerdown', () => this.scene.start('ModeSelectScene'));
   462→  }
   463→
   464→  // ═══════════════════════════════════════════════════
   465→  // 터미널 헬퍼
   466→  // ═══════════════════════════════════════════════════
   467→
   468→  private clearUI() {
   469→    this.tweens.killAll();
   470→    this.time.removeAllEvents();
   471→    this.input.off('pointerdown');
   472→    this.children.getAll().forEach(c => c.destroy());
   473→    this.terminalTexts = [];
   474→  }
   475→
   476→  private typeLines(lines: string[], delay = 40): Promise<void> {
   477→    return lines.reduce(
   478→      (p, line) => p.then(() => this.typeLine(line, delay)),
   479→      Promise.resolve()
   480→    );
   481→  }
   482→
   483→  private typeLine(text: string, charDelay = 40): Promise<void> {
   484→    return new Promise(resolve => {
   485→      if (!this.scene.isActive()) { resolve(); return; }
   486→
   487→      // 최대 6줄 유지 (스크롤 효과)
   488→      if (this.terminalTexts.length >= 6) {
   489→        this.terminalTexts.shift()?.destroy();
   490→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   491→      }
   492→
   493→      const y = 276 + this.terminalTexts.length * 22;
   494→      const t = this.add.text(24, y, '', {
   495→        fontSize: '13px', color: '#00ff41', fontFamily: 'monospace',
   496→      });
   497→      this.terminalTexts.push(t);
   498→
   499→      let i = 0;
   500→      const ev = this.time.addEvent({
   501→        delay: charDelay,
   502→        repeat: text.length,
   503→        callback: () => {
   504→          if (!this.scene.isActive()) { ev.destroy(); resolve(); return; }
   505→          t.setText(text.substring(0, i + 1));
   506→          i++;
   507→          if (i > text.length) { ev.destroy(); resolve(); }
   508→        },
   509→      });
   510→    });
   511→  }
   512→
   513→  private progressBar(duration: number): Promise<void> {
   514→    return new Promise(resolve => {
   515→      if (!this.scene.isActive()) { resolve(); return; }
   516→
   517→      if (this.terminalTexts.length >= 6) {
   518→        this.terminalTexts.shift()?.destroy();
   519→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   520→      }
   521→
   522→      const y = 276 + this.terminalTexts.length * 22;
   523→      const bar = this.add.text(24, y, '> [          ]  0%', {
   524→        fontSize: '13px', color: '#00ff41', fontFamily: 'monospace',
   525→      });
   526→      this.terminalTexts.push(bar);
   527→
   528→      let step = 0;
   529→      const steps = 10;
   530→      const ev = this.time.addEvent({
   531→        delay: duration / steps,
   532→        repeat: steps - 1,
   533→        callback: () => {
   534→          step++;
   535→          bar.setText(`> [${'█'.repeat(step)}${' '.repeat(steps - step)}] ${step * 10}%`);
   536→          if (step >= steps) { ev.destroy(); resolve(); }
   537→        },
   538→      });
   539→    });
   540→  }
   541→
   542→  private sleep(ms: number): Promise<void> {
   543→    return new Promise(resolve => {
   544→      if (!this.scene.isActive()) { resolve(); return; }
   545→      this.time.delayedCall(ms, resolve);
   546→    });
   547→  }
   548→}
