const SKOR_BALANCE_CACHE_KEY = 'skorBalanceCache';

/** 마지막으로 알고 있는 SKOR 잔액을 로컬에서 즉시 반환 (없으면 null) */
export function getCachedSkorBalance(): number | null {
  const raw = localStorage.getItem(SKOR_BALANCE_CACHE_KEY);
