      button.setStrokeStyle(3, 0xaa66ff);
    });
    button.on('pointerout', () => {
      button.setFillStyle(0x1a1a2e);
      button.setStrokeStyle(3, 0x7b2fff);
    });
    button.on('pointerdown', () => {
