    button.setStrokeStyle(2, 0x888888);

    this.add.text(x, y, '🧬 캐릭터', {
      fontSize: '18px',
      color: '#ffffff',
      fontStyle: 'bold',
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });

    button.on('pointerover', () => button.setFillStyle(0x444444));
    button.on('pointerout',  () => button.setFillStyle(0x2a2a2a));
