/** 영상 원본 비율을 유지하면서 캔버스 안에 꽉 차게 (contain) */
private fitVideoToCanvas(vid: Phaser.GameObjects.Video, canvasW: number, canvasH: number) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const el: HTMLVideoElement = (vid as any).video;
  const apply = () => {
    const nw = el.videoWidth  || canvasW;
    const nh = el.videoHeight || canvasH;
    const scale = Math.min(canvasW / nw, canvasH / nh);
    vid.setDisplaySize(nw * scale, nh * scale);
  };
  if (el?.videoWidth) {
    apply();
  } else {
    el?.addEventListener('loadedmetadata', apply, { once: true });
  }
}

