/** 영상 원본 비율을 유지하면서 캔버스 안에 꽉 차게 (contain) */
private fitVideoToCanvas(vid: Phaser.GameObjects.Video, canvasW: number, canvasH: number) {
  const applyContain = () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const el: HTMLVideoElement | null = (vid as any).video ?? null;
    const nw = el?.videoWidth  || 0;
    const nh = el?.videoHeight || 0;
    if (nw > 0 && nh > 0) {
      const scale = Math.min(canvasW / nw, canvasH / nh);
      vid.setDisplaySize(nw * scale, nh * scale);
    } else {
      // 아직 메타데이터 없으면 캔버스 전체로 임시 표시 후 재시도
      vid.setDisplaySize(canvasW, canvasH);
      this.time.delayedCall(200, applyContain);
    }
  };
  applyContain();
}

